insert into seed_mock01 (seq, section, topic, difficulty, stem, option_a, option_b, option_c, option_d, answer, explanation, plus, minus) values
  (1, 'Mathematics', 'Set Theory', 'Easy', 'If A = {1, 2, 3} and B = {3, 4, 5}, how many elements does A ∪ B contain?', '4', '6', '5', '3', 2, 'A ∪ B = {1, 2, 3, 4, 5}. The shared element 3 is counted once, giving 5 elements.', 12, -3),
  (2, 'Mathematics', 'Mathematical Logic', 'Easy', 'The negation of the statement “All NIMCET aspirants are hardworking” is —', 'Some NIMCET aspirants are not hardworking', 'No NIMCET aspirants are hardworking', 'All hardworking people are NIMCET aspirants', 'Some NIMCET aspirants are hardworking', 0, 'The negation of “All S are P” is “Some S are not P”, so the correct negation is “Some NIMCET aspirants are not hardworking”.', 12, -3),
  (3, 'Mathematics', 'Set Theory', 'Medium', 'In a class of 60 students, 35 play cricket, 25 play football and 10 play both games. How many students play neither game?', '20', '15', '5', '10', 3, 'Students playing at least one game = 35 + 25 − 10 = 50. Neither = 60 − 50 = 10.', 12, -3),
  (4, 'Mathematics', 'Relations & Functions', 'Easy', 'If f(x) = 2x + 3, then f(f(1)) equals —', '11', '13', '16', '10', 1, 'f(1) = 2(1) + 3 = 5, then f(5) = 2(5) + 3 = 13.', 12, -3),
  (5, 'Mathematics', 'Relations & Functions', 'Medium', 'The domain of the real function f(x) = √(4 − x²) is —', '[−2, 2]', '(−2, 2)', '[0, 2]', '[−4, 4]', 0, 'The expression under the square root must be non-negative: 4 − x² ≥ 0, i.e. x² ≤ 4, so −2 ≤ x ≤ 2.', 12, -3),
  (6, 'Mathematics', 'Relations & Functions', 'Hard', 'If f(x) = x/(x − 1), then for x ≠ 0, 1 the value of f(f(x)) is —', '1/x', 'x − 1', 'x', '1/(x − 1)', 2, 'f(f(x)) = [x/(x − 1)] ÷ [x/(x − 1) − 1] = [x/(x − 1)] ÷ [1/(x − 1)] = x. So f is its own inverse on its domain.', 12, -3),
  (7, 'Mathematics', 'Logarithms', 'Easy', 'The value of log₂ 32 is —', '4', '5', '8', '6', 1, '32 = 2⁵, so log₂ 32 = 5.', 12, -3),
  (8, 'Mathematics', 'Progressions', 'Medium', 'The 10th term of the arithmetic progression 3, 7, 11, … is —', '35', '40', '43', '39', 3, 'First term a = 3, common difference d = 4. a₁₀ = a + 9d = 3 + 36 = 39.', 12, -3),
  (9, 'Mathematics', 'Progressions', 'Hard', 'The sum of the first 8 terms of the geometric progression 1 + 1/2 + 1/4 + … is —', '255/256', '257/128', '255/128', '127/128', 2, 'S₈ = a(1 − r⁸)/(1 − r) with a = 1, r = 1/2: S₈ = (1 − 1/256)/(1/2) = 2 × 255/256 = 255/128.', 12, -3),
  (10, 'Mathematics', 'Quadratic Equations', 'Medium', 'If α and β are the roots of x² − 5x + 6 = 0, then α² + β² equals —', '13', '11', '12', '25', 0, 'α + β = 5 and αβ = 6. α² + β² = (α + β)² − 2αβ = 25 − 12 = 13.', 12, -3),
  (11, 'Mathematics', 'Theory of Equations', 'Hard', 'The number of real roots of the equation x⁴ − 4x² + 4 = 0 is —', '0', '1', '4', '2', 3, 'x⁴ − 4x² + 4 = (x² − 2)² = 0, so x² = 2, giving x = √2 and x = −√2 — exactly 2 real roots.', 12, -3),
  (12, 'Mathematics', 'Matrices', 'Easy', 'For the matrix A = [[1, 2], [3, 4]], the trace of A (sum of the principal diagonal entries) is —', '4', '5', '10', '7', 1, 'The principal diagonal entries are 1 and 4, so trace(A) = 1 + 4 = 5.', 12, -3),
  (13, 'Mathematics', 'Determinants', 'Medium', 'If A is a 2 × 2 matrix with det(A) = 5, then det(3A) is —', '45', '15', '30', '125', 0, 'For an n × n matrix, det(kA) = kⁿ · det(A). Here n = 2: det(3A) = 3² × 5 = 45.', 12, -3),
  (14, 'Mathematics', 'Determinants', 'Medium', 'If A = [[2, 3], [1, 4]], then det(A⁻¹) equals —', '5', '−5', '1/5', '1/25', 2, 'det(A) = (2)(4) − (3)(1) = 8 − 3 = 5. Since det(A⁻¹) = 1/det(A), the answer is 1/5.', 12, -3),
  (15, 'Mathematics', 'Determinants', 'Hard', 'If A is a 3 × 3 matrix with det(A) = −2, then det(adj A) equals —', '−2', '2', '−4', '4', 3, 'For an n × n matrix, det(adj A) = (det A)^(n−1). Here det(adj A) = (−2)² = 4.', 12, -3),
  (16, 'Mathematics', 'Coordinate Geometry', 'Easy', 'The slope of the line joining the points (1, 2) and (3, 8) is —', '1/3', '3', '6', '2', 1, 'Slope = (8 − 2)/(3 − 1) = 6/2 = 3.', 12, -3),
  (17, 'Mathematics', 'Coordinate Geometry', 'Medium', 'The line 2x − 3y + 6 = 0 meets the x-axis at the point —', '(3, 0)', '(0, 2)', '(−3, 0)', '(0, −2)', 2, 'On the x-axis, y = 0: 2x + 6 = 0 gives x = −3. The point is (−3, 0).', 12, -3),
  (18, 'Mathematics', 'Circles', 'Medium', 'The radius of the circle x² + y² − 4x + 6y − 12 = 0 is —', '5', '√12', '7', '3', 0, 'Centre = (2, −3). r² = 2² + (−3)² − (−12) = 4 + 9 + 12 = 25, so r = 5.', 12, -3),
  (19, 'Mathematics', 'Conic Sections', 'Medium', 'The focus of the parabola y² = 8x is —', '(0, 2)', '(2, 0)', '(4, 0)', '(8, 0)', 1, 'Comparing with y² = 4ax, 4a = 8 gives a = 2. The focus is (a, 0) = (2, 0).', 12, -3),
  (20, 'Mathematics', 'Limits', 'Easy', 'The value of lim(x→0) (sin x)/x is —', '0', '−1', 'Does not exist', '1', 3, 'This is the standard trigonometric limit: lim(x→0) (sin x)/x = 1.', 12, -3),
  (21, 'Mathematics', 'Limits', 'Medium', 'The value of lim(x→2) (x² − 4)/(x − 2) is —', '0', '2', '4', 'Does not exist', 2, 'For x ≠ 2, (x² − 4)/(x − 2) = x + 2. As x → 2, the expression tends to 4.', 12, -3),
  (22, 'Mathematics', 'Differentiation', 'Easy', 'The value of d/dx (x³) at x = 2 is —', '6', '12', '8', '3', 1, 'd/dx (x³) = 3x². At x = 2: 3 × 4 = 12.', 12, -3),
  (23, 'Mathematics', 'Differentiation', 'Medium', 'If y = x·eˣ, then dy/dx equals —', 'eˣ(x + 1)', 'eˣ', 'x·eˣ', 'eˣ(x − 1)', 0, 'By the product rule: dy/dx = eˣ + x·eˣ = eˣ(x + 1).', 12, -3),
  (24, 'Mathematics', 'Application of Derivatives', 'Medium', 'The slope of the tangent to the curve y = x² − 4x + 5 at x = 3 is —', '5', '−2', '6', '2', 3, 'dy/dx = 2x − 4. At x = 3: 6 − 4 = 2.', 12, -3),
  (25, 'Mathematics', 'Application of Derivatives', 'Hard', 'The minimum value of f(x) = x² − 6x + 13 for real x is —', '3', '9', '4', '13', 2, 'x² − 6x + 13 = (x − 3)² + 4. Since (x − 3)² ≥ 0, the minimum value is 4, attained at x = 3.', 12, -3),
  (26, 'Mathematics', 'Integration', 'Easy', '∫ (2x + 3) dx equals —', '2x² + 3x + C', 'x² + 3x + C', 'x² + 3 + C', 'x² + C', 1, 'Integrating term by term: ∫2x dx = x² and ∫3 dx = 3x, so the result is x² + 3x + C.', 12, -3),
  (27, 'Mathematics', 'Definite Integrals', 'Medium', 'The value of ∫₀^(π/2) sin x dx is —', '0', '2', 'π/2', '1', 3, '∫ sin x dx = −cos x. Evaluating from 0 to π/2: −cos(π/2) − (−cos 0) = 0 + 1 = 1.', 12, -3),
  (28, 'Mathematics', 'Definite Integrals', 'Medium', 'The value of ∫₁² (1/x) dx is —', 'ln 2', '1/2', '2 ln 2', '1', 0, '∫ (1/x) dx = ln x. Evaluating from 1 to 2: ln 2 − ln 1 = ln 2.', 12, -3),
  (29, 'Mathematics', 'Probability', 'Easy', 'A fair coin is tossed twice. The probability of getting exactly one head is —', '1/4', '1/2', '3/4', '1/3', 1, 'The four outcomes HH, HT, TH, TT are equally likely. Exactly one head occurs in HT and TH — 2 of 4, i.e. 1/2.', 12, -3),
  (30, 'Mathematics', 'Probability', 'Medium', 'Two fair dice are thrown. The probability that the sum of the numbers is a multiple of 3 is —', '1/6', '1/4', '1/3', '5/36', 2, 'Favourable sums are 3, 6, 9, 12 with 2, 5, 4 and 1 outcomes respectively — 12 of 36 total outcomes, i.e. 1/3.', 12, -3),
  (31, 'Mathematics', 'Probability', 'Hard', 'A bag contains 4 white and 5 black balls. Two balls are drawn at random without replacement. The probability that both are white is —', '2/9', '1/4', '4/9', '1/6', 3, 'Number of ways to choose 2 of 4 white balls is C(4, 2) = 6; choosing any 2 of 9 balls is C(9, 2) = 36. Probability = 6/36 = 1/6.', 12, -3),
  (32, 'Mathematics', 'Statistics', 'Medium', 'The arithmetic mean of the data 2, 4, 4, 4, 5, 5, 7, 9 is —', '4', '5.5', '5', '6', 2, 'Sum = 2 + 4 + 4 + 4 + 5 + 5 + 7 + 9 = 40, and there are 8 observations. Mean = 40/8 = 5.', 12, -3),
  (33, 'Mathematics', 'Statistics', 'Easy', 'The median of the data 3, 8, 5, 9, 4 is —', '5', '4', '5.5', '8', 0, 'Arranged in order: 3, 4, 5, 8, 9. The middle (third) value is 5.', 12, -3),
  (34, 'Mathematics', 'Trigonometry', 'Hard', 'The value of sin 75° is —', '(√6 − √2)/4', '(√6 + √2)/4', '(√3 + 1)/2', '(√3 − 1)/2', 1, 'sin 75° = sin(45° + 30°) = sin 45° cos 30° + cos 45° sin 30° = (√6 + √2)/4.', 12, -3),
  (35, 'Mathematics', 'Trigonometry', 'Easy', 'If tan θ = 3/4 for an acute angle θ, then sin θ equals —', '4/5', '5/3', '3/5', '4/3', 2, 'tan θ = 3/4 gives a 3-4-5 right triangle with opposite 3, adjacent 4 and hypotenuse 5, so sin θ = 3/5.', 12, -3),
  (36, 'Mathematics', 'Trigonometry', 'Medium', 'The value of cos 2θ + 2 sin²θ is —', '0', '2', 'sin²θ', '1', 3, 'cos 2θ = 1 − 2 sin²θ, so cos 2θ + 2 sin²θ = 1 for every θ.', 12, -3),
  (37, 'Mathematics', 'Trigonometric Equations', 'Medium', 'The number of solutions of sin x = 1/2 in the interval [0, 2π] is —', '1', '4', '2', '3', 2, 'In [0, 2π), sin x = 1/2 at x = π/6 and x = 5π/6 — two solutions.', 12, -3),
  (38, 'Mathematics', 'Vectors', 'Easy', 'If a = 2i + 3j and b = i − j, then a + b equals —', '3i + 2j', '3i + 4j', 'i + 4j', '2i − 3j', 0, 'Adding component-wise: (2 + 1)i + (3 − 1)j = 3i + 2j.', 12, -3),
  (39, 'Mathematics', 'Vectors', 'Easy', 'The dot product (2i + j) · (i + 3j) is —', '4', '5', '6', '7', 1, '(2)(1) + (1)(3) = 2 + 3 = 5.', 12, -3),
  (40, 'Mathematics', 'Vectors', 'Medium', 'The angle between the vectors i + j and j + k is —', '30°', '45°', '60°', '90°', 2, 'Dot product = 1 and both vectors have magnitude √2, so cos θ = 1/(√2·√2) = 1/2, giving θ = 60°.', 12, -3),
  (41, 'Mathematics', 'Vectors', 'Hard', 'If a = i + j and b = i − j, then |a × b| equals —', '0', '1', '√2', '2', 3, 'a × b = −2k (component-wise cross product), whose magnitude is 2. Alternatively, |a × b| = |a||b| sin 90° = √2 · √2 = 2.', 12, -3),
  (42, 'Mathematics', 'Arithmetic', 'Easy', 'If 15% of a number x is 45, then x equals —', '300', '250', '275', '450', 0, '0.15x = 45 gives x = 45/0.15 = 300.', 12, -3),
  (43, 'Mathematics', 'Arithmetic', 'Easy', 'The simple interest on ₹5,000 at 8% per annum for 2 years is —', '₹400', '₹800', '₹820', '₹1,600', 1, 'SI = P·R·T/100 = 5000 × 8 × 2 / 100 = ₹800.', 12, -3),
  (44, 'Mathematics', 'Arithmetic', 'Medium', '₹1,260 is divided among three people in the ratio 2 : 3 : 4. The largest share is —', '₹280', '₹420', '₹560', '₹630', 2, 'Total parts = 2 + 3 + 4 = 9. The largest share is (4/9) × 1260 = ₹560.', 12, -3),
  (45, 'Mathematics', 'Arithmetic', 'Medium', 'The compound interest on ₹1,000 at 10% per annum for 2 years, compounded annually, is —', '₹210', '₹200', '₹220', '₹1,210', 0, 'Amount = 1000 × (1.1)² = ₹1,210. Compound interest = 1210 − 1000 = ₹210.', 12, -3),
  (46, 'Mathematics', 'Arithmetic', 'Medium', 'A can complete a piece of work in 10 days and B can complete it in 15 days. Working together, they will finish it in —', '5 days', '6 days', '8 days', '12.5 days', 1, 'One day''s work = 1/10 + 1/15 = 1/6 of the job, so together they need 6 days.', 12, -3),
  (47, 'Mathematics', 'Binomial Theorem', 'Medium', 'The coefficient of x² in the expansion of (1 + x)⁵ is —', '5', '15', '10', '20', 2, 'The coefficient is C(5, 2) = 10.', 12, -3),
  (48, 'Mathematics', 'Inequalities', 'Hard', 'The solution set of the inequality |2x − 3| < 5 is —', '(−4, 1)', '(1, 4)', '[−1, 4]', '(−1, 4)', 3, '−5 < 2x − 3 < 5 gives −2 < 2x < 8, i.e. −1 < x < 4. The solution set is (−1, 4).', 12, -3),
  (49, 'Mathematics', 'Complex Numbers', 'Medium', 'If z = 1 + i, then z² equals —', '2i', '2', '−2i', '1 + 2i', 0, '(1 + i)² = 1 + 2i + i² = 1 + 2i − 1 = 2i.', 12, -3),
  (50, 'Mathematics', 'Matrices', 'Medium', 'If the rows of a 3 × 3 matrix are linearly dependent, then its determinant is —', '1', '0', '−1', 'Undefined', 1, 'Linearly dependent rows make the matrix singular, and a singular matrix has determinant 0.', 12, -3),
  (51, 'Analytical Reasoning', 'Number Series', 'Easy', 'Find the next term in the series: 5, 10, 20, 40, ?', '60', '80', '100', '120', 1, 'Each term is double the previous one (×2), so the next term is 40 × 2 = 80.', 6, -1.5),
  (52, 'Analytical Reasoning', 'Number Series', 'Easy', 'Find the next term in the series: 2, 3, 5, 7, 11, ?', '15', '17', '12', '13', 3, 'The series lists consecutive prime numbers. The next prime after 11 is 13.', 6, -1.5),
  (53, 'Analytical Reasoning', 'Number Series', 'Easy', 'Find the next term in the series: 1, 4, 9, 16, 25, ?', '36', '49', '30', '64', 0, 'The terms are perfect squares 1², 2², 3², 4², 5²; the next is 6² = 36.', 6, -1.5),
  (54, 'Analytical Reasoning', 'Number Series', 'Hard', 'Find the next term in the series: 3, 7, 16, 35, ?', '70', '72', '74', '76', 2, 'The pattern is ×2 + 1, ×2 + 2, ×2 + 3: 3 → 7 → 16 → 35, so the next term is 35 × 2 + 4 = 74.', 6, -1.5),
  (55, 'Analytical Reasoning', 'Number Series', 'Medium', 'Find the next term in the series: 8, 6, 9, 7, 10, ?', '9', '8', '11', '7', 1, 'The operations alternate: −2, +3, −2, +3, so after 10 the next term is 10 − 2 = 8.', 6, -1.5),
  (56, 'Analytical Reasoning', 'Letter Series', 'Medium', 'Find the next letter in the series: A, C, F, J, ?', 'L', 'M', 'N', 'O', 3, 'The letter positions jump by +2, +3, +4, so the next jump is +5: J (10) + 5 = 15 = O.', 6, -1.5),
  (57, 'Analytical Reasoning', 'Coding-Decoding', 'Easy', 'In a certain code, MOUSE is written as NPVTF. How is WISE written in that code?', 'XJTF', 'XITF', 'XJSF', 'YJTF', 0, 'Each letter shifts one step forward: M→N, O→P, U→V, S→T, E→F. Applying the same rule: W→X, I→J, S→T, E→F, giving XJTF.', 6, -1.5),
  (58, 'Analytical Reasoning', 'Coding-Decoding', 'Medium', 'In a certain code, RAM is written as 32 (R = 18, A = 1, M = 13, and 18 + 1 + 13 = 32). Using the same code, TOP is written as —', '48', '49', '51', '53', 2, 'Sum the alphabetical positions: T = 20, O = 15, P = 16, and 20 + 15 + 16 = 51.', 6, -1.5),
  (59, 'Analytical Reasoning', 'Coding-Decoding', 'Medium', 'In a certain code, MANAGER is written as RENAGAM. How is DIRECTOR written in that code?', 'ROTCERID', 'ROTCIRED', 'ROTECRID', 'DETCERID', 0, 'The code is simply the word written backwards: MANAGER reversed is RENAGAM. DIRECTOR reversed is ROTCERID (the 5th letter of DIRECTOR is C, so the reversed 4th letter is C, not E).', 6, -1.5),
  (60, 'Analytical Reasoning', 'Blood Relations', 'Easy', 'Pointing to a photograph, Ravi says, “She is the daughter of my grandfather''s only son.” How is the girl related to Ravi?', 'Mother', 'Aunt', 'Cousin', 'Sister', 3, 'Ravi''s grandfather''s only son is Ravi''s father. The daughter of Ravi''s father is Ravi''s sister.', 6, -1.5),
  (61, 'Analytical Reasoning', 'Blood Relations', 'Medium', 'A is B''s mother. B is C''s sister. D is C''s father. How is A related to D?', 'Wife', 'Sister', 'Daughter', 'Mother-in-law', 0, 'B and C are siblings, so they share the same parents. A is B''s mother and D is C''s father, so A and D are the parents of the same children — A is D''s wife.', 6, -1.5),
  (62, 'Analytical Reasoning', 'Direction Sense', 'Easy', 'A man walks 5 km towards the north, then turns and walks 12 km towards the east. How far is he from his starting point?', '17 km', '7 km', '13 km', '12 km', 2, 'The two legs are perpendicular, so the distance is √(5² + 12²) = √169 = 13 km.', 6, -1.5),
  (63, 'Analytical Reasoning', 'Direction Sense', 'Medium', 'A person faces north. He turns 90° right, then 90° right again, and finally turns 90° left. Which direction is he facing now?', 'East', 'South', 'West', 'North', 0, 'North → right → East; East → right → South; South → left → East. He ends up facing east.', 6, -1.5),
  (64, 'Analytical Reasoning', 'Direction Sense', 'Medium', 'Sunil walks 3 km towards the east, then turns left and walks 4 km. His displacement from the starting point is —', '5 km towards the south-east', '5 km towards the north-east', '7 km towards the north-east', '4 km towards the north', 1, 'Facing east, a left turn points him north. He ends 3 km east and 4 km north of the start, i.e. 5 km towards the north-east (√(3² + 4²) = 5).', 6, -1.5),
  (65, 'Analytical Reasoning', 'Syllogism', 'Medium', 'Statements: All roses are flowers. Some flowers fade quickly. Conclusions: I. Some roses fade quickly. II. All flowers are roses. Which conclusion(s) follow(s)?', 'Only I follows', 'Only II follows', 'Neither I nor II follows', 'Both I and II follow', 2, 'The flowers that fade quickly need not include any rose, so I does not follow. “All roses are flowers” does not imply “all flowers are roses”, so II does not follow either.', 6, -1.5),
  (66, 'Analytical Reasoning', 'Syllogism', 'Easy', 'Statements: All engineers are graduates. All graduates are educated. Which conclusion follows?', 'All engineers are educated', 'All educated persons are engineers', 'Some engineers are not educated', 'No engineer is a graduate', 0, 'Engineers ⊆ graduates ⊆ educated, so all engineers are educated. The converse and the negative statements do not follow.', 6, -1.5),
  (67, 'Analytical Reasoning', 'Syllogism', 'Hard', 'Statements: No cat is a dog. All dogs are animals. Conclusions: I. No cat is an animal. II. Some animals are dogs. Which conclusion(s) follow(s)?', 'Only I follows', 'Both I and II follow', 'Neither follows', 'Only II follows', 3, 'I does not follow — cats may be animals that are not dogs. II follows, because every dog is an animal and dogs exist, so some animals are dogs.', 6, -1.5),
  (68, 'Analytical Reasoning', 'Seating Arrangement', 'Medium', 'Five friends A, B, C, D and E sit in a row facing north. C sits at the extreme left and E is to the immediate right of C. B sits between E and A, and D sits at the extreme right. Who sits in the middle of the row?', 'A', 'B', 'C', 'E', 1, 'The row from left to right is C, E, B, A, D. The middle (third) seat is occupied by B.', 6, -1.5),
  (69, 'Analytical Reasoning', 'Seating Arrangement', 'Hard', 'Five friends A, B, C, D and E sit around a circular table facing the centre. B is to the immediate right of A, C is second to the left of A, and D sits between C and B. Who sits immediately to the left of C?', 'A', 'B', 'D', 'E', 2, 'Fix A and arrange clockwise (facing the centre, left = clockwise): with A at a seat, B is immediately anti-clockwise, C is two seats clockwise of A, and D must be the seat between C and B. E takes the remaining seat. The seat immediately clockwise of C — C''s immediate left — is D.', 6, -1.5),
  (70, 'Analytical Reasoning', 'Arithmetic Reasoning', 'Medium', 'The sum of the present ages of a father and his son is 60 years. Five years ago, the father was four times as old as the son. The son''s present age is —', '15 years', '12 years', '18 years', '20 years', 0, 'Let the son''s present age be s; the father''s is 60 − s. Five years ago: (60 − s − 5) = 4(s − 5), i.e. 55 − s = 4s − 20, giving 5s = 75 and s = 15.', 6, -1.5),
  (71, 'Analytical Reasoning', 'Arrangement Puzzle', 'Easy', 'Four boxes R, G, B and Y are stacked one above the other. R is above G, B is above R, and Y is at the bottom. Which box is at the top?', 'R', 'G', 'Y', 'B', 3, 'The order from top to bottom must be B, R, G, Y — B is above R, R is above G, and G is above Y. So B is at the top.', 6, -1.5),
  (72, 'Analytical Reasoning', 'Letter Series', 'Easy', 'Find the next letter in the series: Z, X, V, T, ?', 'S', 'R', 'Q', 'P', 1, 'Each letter is two positions before the previous one alphabetically: Z → X → V → T → R.', 6, -1.5),
  (73, 'Analytical Reasoning', 'Classification', 'Medium', 'Three of the following numbers are perfect squares. Which one is the odd one out?', '16', '25', '36', '42', 3, '16 = 4², 25 = 5² and 36 = 6² are perfect squares; 42 is not a perfect square.', 6, -1.5),
  (74, 'Analytical Reasoning', 'Analogy', 'Easy', 'Doctor : Hospital :: Teacher : ?', 'School', 'Books', 'Students', 'Principal', 0, 'A doctor''s primary workplace is a hospital; likewise, a teacher''s primary workplace is a school.', 6, -1.5),
  (75, 'Analytical Reasoning', 'Analogy', 'Medium', '6 : 42 :: 7 : ?', '49', '54', '56', '63', 2, 'The pattern is n : n × (n + 1). For 6: 6 × 7 = 42; for 7: 7 × 8 = 56.', 6, -1.5),
  (76, 'Analytical Reasoning', 'Classification', 'Medium', 'Three of the following groups consist entirely of prime numbers. Which group does not?', '3, 5, 7', '2, 4, 6', '11, 13, 17', '19, 23, 29', 1, 'In the group 2, 4, 6 only 2 is prime — 4 and 6 are composite, so this group is the odd one out.', 6, -1.5),
  (77, 'Analytical Reasoning', 'Data Interpretation', 'Easy', 'In a school of 800 students, 45% are girls. How many boys study in the school?', '440', '360', '450', '480', 0, 'Girls = 45% of 800 = 360. Boys = 800 − 360 = 440.', 6, -1.5),
  (78, 'Analytical Reasoning', 'Data Interpretation', 'Medium', 'The production of a factory over four consecutive years was 200, 250, 300 and 350 units. The percentage increase in production from the first year to the fourth year is —', '50%', '150%', '75%', '175%', 2, 'Increase = 350 − 200 = 150 units on a base of 200, i.e. (150/200) × 100 = 75%.', 6, -1.5),
  (79, 'Analytical Reasoning', 'Data Interpretation', 'Hard', 'In an examination, 60% of the students passed Mathematics, 50% passed English and 30% passed both subjects. The percentage of students who failed in both subjects is —', '30%', '20%', '10%', '40%', 1, 'Students passing at least one subject = 60 + 50 − 30 = 80%. Those failing both = 100 − 80 = 20%.', 6, -1.5),
  (80, 'Analytical Reasoning', 'Syllogism', 'Medium', 'Statements: Some pens are books. All books are pencils. Conclusions: I. Some pens are pencils. II. All pencils are pens. Which conclusion(s) follow(s)?', 'Only II follows', 'Both follow', 'Neither follows', 'Only I follows', 3, 'Some pens are books and all books are pencils, so those pens are pencils — I follows. II does not follow: pencils that are not books (and not pens) may exist.', 6, -1.5),
  (81, 'Analytical Reasoning', 'Number Series', 'Hard', 'Find the next term in the series: 2, 12, 36, 80, 150, ?', '240', '252', '280', '294', 1, 'Each term is n³ + n² for n = 1, 2, 3, …: 1+1=2, 8+4=12, 27+9=36, 64+16=80, 125+25=150, and for n = 6: 216 + 36 = 252.', 6, -1.5),
  (82, 'Analytical Reasoning', 'Number Series', 'Easy', 'Find the next term in the series: 1, 1, 2, 3, 5, 8, ?', '11', '12', '13', '15', 2, 'This is the Fibonacci series: each term is the sum of the two preceding terms. 5 + 8 = 13.', 6, -1.5),
  (83, 'Analytical Reasoning', 'Number Series', 'Medium', 'Find the next term in the series: 10, 9, 11, 8, 12, 7, ?', '13', '6', '14', '11', 0, 'The differences are −1, +2, −3, +4, −5, so the next difference is +6: 7 + 6 = 13.', 6, -1.5),
  (84, 'Analytical Reasoning', 'Symbol Operations', 'Hard', 'If A # B is defined as A³ − B², then the value of 3 # 2 is —', '19', '31', '5', '23', 3, '3³ − 2² = 27 − 4 = 23.', 6, -1.5),
  (85, 'Analytical Reasoning', 'Calendar', 'Medium', 'If 1 January 2024 was a Monday, what day of the week was 1 February 2024?', 'Wednesday', 'Thursday', 'Friday', 'Sunday', 1, 'January has 31 days, and 31 = 4 weeks + 3 days. Three days after Monday is Thursday.', 6, -1.5),
  (86, 'Analytical Reasoning', 'Clocks', 'Easy', 'What is the angle between the hour hand and the minute hand of a clock at exactly 3 o''clock?', '60°', '120°', '90°', '30°', 2, 'At 3 o''clock the minute hand points at 12 and the hour hand at 3, exactly one quarter of the circle apart: 90°.', 6, -1.5),
  (87, 'Analytical Reasoning', 'Analogy', 'Easy', 'Book : Chapter :: Building : ?', 'Floor', 'Brick', 'Architect', 'Cement', 0, 'A chapter is a major division of a book; a floor is a major division of a building.', 6, -1.5),
  (88, 'Analytical Reasoning', 'Classification', 'Medium', 'Three of the following are outdoor field games. Which one is the odd one out?', 'Cricket', 'Football', 'Hockey', 'Chess', 3, 'Cricket, football and hockey are outdoor field games; chess is an indoor board game.', 6, -1.5),
  (89, 'Analytical Reasoning', 'Number Logic', 'Medium', 'How many integers from 1 to 50 are divisible by 3 or 5?', '20', '23', '24', '26', 1, 'Divisible by 3: 16 numbers. By 5: 10 numbers. By both (15): 3 numbers. 16 + 10 − 3 = 23.', 6, -1.5),
  (90, 'Analytical Reasoning', 'Logical Deduction', 'Hard', 'If it rains, the match is cancelled. The match was not cancelled. Therefore —', 'It rained', 'Cannot be determined', 'It did not rain', 'The match was postponed', 2, 'The given statement is of the form “If P then Q”. Its contrapositive “If not Q then not P” is always true: since Q (cancellation) is false, P (rain) must be false as well.', 6, -1.5),
  (91, 'Computer Awareness', 'Computer Fundamentals', 'Easy', 'Which component is called the brain of the computer?', 'RAM', 'Hard Disk', 'CPU', 'Monitor', 2, 'The CPU (Central Processing Unit) performs all processing and controls the other units, so it is called the brain of the computer.', 6, -1.5),
  (92, 'Computer Awareness', 'Memory', 'Easy', 'Which of the following is a volatile memory?', 'RAM', 'ROM', 'SSD', 'Hard Disk', 0, 'RAM loses its contents when power is switched off, so it is volatile. ROM, SSD and hard disks retain data without power.', 6, -1.5),
  (93, 'Computer Awareness', 'Memory', 'Easy', '1 GB is equal to how many megabytes (MB)?', '1000', '1024', '512', '2048', 1, 'In binary units, 1 GB = 2¹⁰ MB = 1024 MB.', 6, -1.5),
  (94, 'Computer Awareness', 'Software', 'Easy', 'Which of the following is NOT an operating system?', 'Windows', 'Linux', 'Ubuntu', 'Oracle', 3, 'Windows, Linux and Ubuntu are operating systems. Oracle is a database management system, not an OS.', 6, -1.5),
  (95, 'Computer Awareness', 'Number Systems', 'Medium', 'The binary number 1010 is equal to which decimal number?', '8', '12', '16', '10', 3, '1010₂ = 1×2³ + 0×2² + 1×2¹ + 0×2⁰ = 8 + 0 + 2 + 0 = 10.', 6, -1.5),
  (96, 'Computer Awareness', 'Number Systems', 'Medium', 'The hexadecimal number 1F is equal to which decimal number?', '32', '31', '15', '17', 1, '1F₁₆ = 1×16 + F×1 = 16 + 15 = 31.', 6, -1.5),
  (97, 'Computer Awareness', 'Networking', 'Medium', 'Which service translates human-readable domain names such as www.example.com into IP addresses?', 'DNS', 'FTP', 'SMTP', 'HTTP', 0, 'DNS (Domain Name System) resolves domain names to the corresponding IP addresses. FTP transfers files, SMTP sends mail and HTTP serves web pages.', 6, -1.5),
  (98, 'Computer Awareness', 'Networking', 'Medium', 'Which network device is used to connect two different networks and forward data between them?', 'Switch', 'Hub', 'Router', 'Repeater', 2, 'A router forwards data packets between different networks (for example, a home network and the internet). Switches and hubs work within one network; a repeater only regenerates signals.', 6, -1.5),
  (99, 'Computer Awareness', 'Networking', 'Easy', 'The OSI reference model divides network communication into how many layers?', '5', '7', '9', '4', 1, 'The OSI model has 7 layers: Physical, Data Link, Network, Transport, Session, Presentation and Application.', 6, -1.5),
  (100, 'Computer Awareness', 'Database Management', 'Medium', 'In a relational database, which key uniquely identifies each row of a table?', 'Primary key', 'Foreign key', 'Candidate key', 'Composite name', 0, 'The primary key uniquely identifies every row of a table and cannot contain duplicates or nulls. A foreign key instead references a key in another table.', 6, -1.5),
  (101, 'Computer Awareness', 'Database Management', 'Easy', 'Which SQL command is used to retrieve data from a database table?', 'INSERT', 'UPDATE', 'SELECT', 'DELETE', 2, 'SELECT fetches rows from a table. INSERT adds rows, UPDATE modifies them and DELETE removes them.', 6, -1.5),
  (102, 'Computer Awareness', 'Database Management', 'Medium', 'Which of the following is a NoSQL database?', 'MongoDB', 'MySQL', 'PostgreSQL', 'Oracle', 0, 'MongoDB is a document-oriented NoSQL database. MySQL, PostgreSQL and Oracle are relational (SQL) database systems.', 6, -1.5),
  (103, 'Computer Awareness', 'Programming Concepts', 'Medium', 'Which translator converts an entire high-level program into machine code before execution?', 'Interpreter', 'Compiler', 'Debugger', 'Loader', 1, 'A compiler translates the whole program at once into machine code before it runs; an interpreter instead executes it line by line. Debuggers and loaders do not translate source code.', 6, -1.5),
  (104, 'Computer Awareness', 'Algorithms', 'Medium', 'The worst-case time complexity of binary search on a sorted array of n elements is —', 'O(n)', 'O(n log n)', 'O(1)', 'O(log n)', 3, 'Binary search halves the search space with every comparison, so it needs at most O(log n) comparisons even in the worst case.', 6, -1.5),
  (105, 'Computer Awareness', 'Data Structures', 'Medium', 'Which data structure is used to implement breadth-first search (BFS) of a graph?', 'Stack', 'Heap', 'Queue', 'Tree', 2, 'BFS visits vertices level by level using a queue (First-In, First-Out). A stack is used for depth-first search.', 6, -1.5),
  (106, 'Computer Awareness', 'Web Technologies', 'Medium', 'What does the HTTP status code 404 indicate?', 'Not Found', 'Internal Server Error', 'Unauthorized', 'Moved Permanently', 0, '404 means the requested resource was not found on the server. 500 is Internal Server Error, 401 is Unauthorized and 301 is Moved Permanently.', 6, -1.5),
  (107, 'Computer Awareness', 'Web Technologies', 'Medium', 'A login form must send the password in the request body rather than in the URL. Which form method attribute should be used?', 'GET', 'POST', 'HEAD', 'DELETE', 1, 'POST submits the form data in the request body, so it does not appear in the URL (or in browser history). GET appends data to the URL as query parameters.', 6, -1.5),
  (108, 'Computer Awareness', 'Operating Systems', 'Hard', 'In an operating system, a deadlock occurs when —', 'a process runs forever in an infinite loop', 'two programs open the same file simultaneously', 'a program waits for the user to press a key', 'two or more processes wait indefinitely for resources held by each other', 3, 'A deadlock is a state in which each process holds a resource the others need, so all of them wait forever and none can proceed.', 6, -1.5),
  (109, 'Computer Awareness', 'Cyber Security', 'Medium', 'Phishing is best described as —', 'a fraudulent attempt to obtain sensitive information by impersonating a trusted entity', 'a virus that encrypts files and demands payment', 'a technique to speed up network traffic', 'a method of physically stealing a computer', 0, 'Phishing uses fake emails, messages or websites that imitate trusted organisations to trick users into revealing passwords, card numbers or other sensitive data.', 6, -1.5),
  (110, 'Computer Awareness', 'Memory', 'Medium', 'In the memory hierarchy of a computer, which cache is typically the fastest and closest to the CPU?', 'L3 cache', 'RAM', 'L1 cache', 'SSD', 2, 'L1 cache sits inside the CPU core and is the smallest and fastest cache; L2 and L3 are progressively larger and slower, and RAM is slower still.', 6, -1.5),
  (111, 'General English', 'Vocabulary', 'Easy', 'Choose the word most similar in meaning to “candid”.', 'Rude', 'Cunning', 'Frank', 'Shy', 2, '“Candid” means honest and straightforward, i.e. frank. It does not mean rude, cunning or shy.', 4, -1),
  (112, 'General English', 'Vocabulary', 'Easy', 'Choose the word most opposite in meaning to “transparent”.', 'Opaque', 'Clear', 'Visible', 'Fragile', 0, '“Transparent” means that light passes through so objects behind can be seen; its opposite is “opaque”, through which one cannot see.', 4, -1),
  (113, 'General English', 'One-word Substitution', 'Medium', 'One who is indifferent to pleasure and pain is called —', 'Epicurean', 'Stoic', 'Cynic', 'Optimist', 1, 'A stoic endures pleasure and pain without showing feeling. An epicurean seeks pleasure, a cynic questions others'' motives, and an optimist expects the best.', 4, -1),
  (114, 'General English', 'Idioms', 'Medium', 'The idiom “to spill the beans” means —', 'To waste food', 'To start a quarrel', 'To work very hard', 'To reveal a secret', 3, '“To spill the beans” means to reveal secret information, usually unintentionally.', 4, -1),
  (115, 'General English', 'Grammar', 'Medium', 'Choose the correct form: “Neither of the two candidates ___ qualified.”', 'was', 'were', 'are', 'have been', 0, '“Neither of” takes a singular verb, so “was” is correct: neither (one) of the two candidates was qualified.', 4, -1),
  (116, 'General English', 'Grammar', 'Medium', 'Which of the following sentences is grammatically correct?', 'One of my friend is a doctor.', 'One of my friends are a doctor.', 'One of my friends is a doctor.', 'One of my friend are a doctor.', 2, '“One of” must be followed by a plural noun (“friends”) and a singular verb (“is”), because the subject is “one”.', 4, -1),
  (117, 'General English', 'Grammar', 'Hard', 'Choose the correct form: “The number of applicants ___ increasing every year.”', 'are', 'were', 'have been', 'is', 3, 'The subject here is “the number” (singular), not “applicants”, so the singular verb “is” is correct. Note the contrast with “a number of applicants are…”, where the subject is plural.', 4, -1),
  (118, 'General English', 'Sentence Correction', 'Medium', 'Which version of the sentence is correct?', 'He is senior than me.', 'He is senior to me.', 'He is more senior than me.', 'He is seniorer than me.', 1, 'Latin comparatives such as senior, junior, superior and inferior take “to”, not “than”: “He is senior to me.”', 4, -1),
  (119, 'General English', 'Reading Comprehension', 'Medium', 'Read the passage and answer the question.
insert into public.questions (exam, section, topic, difficulty, stem, options, answer, explanation, plus, minus)
insert into public.tests (exam, title, tag, minutes, free, published, question_ids, description, instructions, sections)
