-- regenerate instead.
--
-- HOW TO RUN (one paste):
--   Supabase Dashboard → SQL Editor → New query → paste this whole file → Run.
--
-- Idempotent and non-destructive: re-running never duplicates questions (rows
-- are matched by exact stem) and never deletes anything. The test row is
-- created on first run and refreshed (same row id, attempt history intact) on
-- later runs, so the linked question_ids always match this file.
--
-- Bundles the additive column from supabase/migrations/0006_test_sections.sql
-- (tests.sections), so no separate migration run is required.
-- ============================================================================

begin;

-- 1. Additive schema: optional timed parts for sectioned mocks.
alter table public.tests
  add column if not exists sections jsonb not null default '[]'::jsonb;

-- 2. Stage the authored paper (ordered by seq).
drop table if exists pg_temp.seed_mock01;
create temporary table seed_mock01 (
  seq         int primary key,
  section     text not null,
  topic       text not null,
  difficulty  text not null,
  stem        text not null,
  option_a    text not null,
  option_b    text not null,
  option_c    text not null,
  option_d    text not null,
  answer      int  not null,
  explanation text not null,
  plus        numeric not null,
  minus       numeric not null
) on commit drop;


Alexander Fleming discovered penicillin in 1928 quite by accident. A petri dish containing staphylococci had been left uncovered, and a mould grew on it. Fleming noticed a clear halo around the mould where the bacteria had been destroyed. He identified the antibacterial substance produced by the mould and named it penicillin. Although Fleming could not purify it in usable quantities, Howard Florey and Ernst Chain later succeeded in mass-producing it during the 1940s, saving millions of lives.

Question: According to the passage, what did Fleming observe on the petri dish?', 'The mould had killed the entire colony of staphylococci', 'The bacteria had grown over the mould', 'A clear halo around the mould where the bacteria had been destroyed', 'The dish had been contaminated by penicillin from another experiment', 2, 'The passage states that Fleming noticed “a clear halo around the mould where the bacteria had been destroyed”. The other options go beyond or contradict the passage.', 4, -1),
  (120, 'General English', 'Reading Comprehension', 'Medium', 'Read the passage and answer the question.

Alexander Fleming discovered penicillin in 1928 quite by accident. A petri dish containing staphylococci had been left uncovered, and a mould grew on it. Fleming noticed a clear halo around the mould where the bacteria had been destroyed. He identified the antibacterial substance produced by the mould and named it penicillin. Although Fleming could not purify it in usable quantities, Howard Florey and Ernst Chain later succeeded in mass-producing it during the 1940s, saving millions of lives.

Question: Who succeeded in mass-producing penicillin?', 'Florey and Chain', 'Fleming alone', 'Fleming and Florey', 'Chain and Fleming', 0, 'The passage says that although Fleming could not purify it in usable quantities, Howard Florey and Ernst Chain later succeeded in mass-producing it.', 4, -1);

-- 3. Insert only questions that do not exist yet (matched by exact stem).
select 'nimcet', s.section, s.topic, s.difficulty, s.stem,
       jsonb_build_array(s.option_a, s.option_b, s.option_c, s.option_d),
       s.answer, s.explanation, s.plus, s.minus
from seed_mock01 s
where not exists (select 1 from public.questions q where q.stem = s.stem);

-- 4. Create the test if it does not exist, then refresh it on every run.
select 'nimcet', 'NIMCET Mock Test 01 — Full Length', 'Full-length', 120, true, true,
       (select array_agg(x.id order by s.seq)
          from seed_mock01 s
          join lateral (
            select q.id from public.questions q
            where q.stem = s.stem
            order by q.created_at
            limit 1
          ) x on true),
       'Full-length MCA entrance practice paper built on the official NIMCET pattern — 120 questions across Mathematics (50), Analytical Ability & Logical Reasoning (40), Computer Awareness (20) and General English (10), with section-wise marking (+12/−3, +6/−1.5, +6/−1.5, +4/−1) and sectional timing (70 + 30 + 20 minutes).',
       'Read all instructions carefully before you begin.

• The paper has 3 timed parts: Mathematics — 50 questions, 70 minutes; Analytical Ability & Logical Reasoning — 40 questions, 30 minutes; Computer Awareness & General English — 30 questions, 20 minutes.
• Each section runs on its own clock. When a section''s time ends it is locked and you are moved to the next section automatically.
• Marking: Mathematics +12 / −3 · Analytical Ability & Logical Reasoning +6 / −1.5 · Computer Awareness +6 / −1.5 · General English +4 / −1.
• There is no penalty for unanswered questions.
• Use the palette to navigate within the current section, and mark questions for review to revisit them before the section ends.
• The paper is auto-submitted when the final section ends; you may also submit early from the header.
• Answers are scored on the server. Correct answers and explanations appear on your scorecard only after you submit.',
       '[{"label":"Mathematics","minutes":70,"count":50},{"label":"Analytical Ability & Logical Reasoning","minutes":30,"count":40},{"label":"Computer Awareness & General English","minutes":20,"count":30}]'::jsonb
where not exists (select 1 from public.tests where title = 'NIMCET Mock Test 01 — Full Length');

update public.tests t set
  question_ids = (select array_agg(x.id order by s.seq)
                    from seed_mock01 s
                    join lateral (
                      select q.id from public.questions q
                      where q.stem = s.stem
                      order by q.created_at
                      limit 1
                    ) x on true),
  sections     = '[{"label":"Mathematics","minutes":70,"count":50},{"label":"Analytical Ability & Logical Reasoning","minutes":30,"count":40},{"label":"Computer Awareness & General English","minutes":20,"count":30}]'::jsonb,
  description  = 'Full-length MCA entrance practice paper built on the official NIMCET pattern — 120 questions across Mathematics (50), Analytical Ability & Logical Reasoning (40), Computer Awareness (20) and General English (10), with section-wise marking (+12/−3, +6/−1.5, +6/−1.5, +4/−1) and sectional timing (70 + 30 + 20 minutes).',
  instructions = 'Read all instructions carefully before you begin.

• The paper has 3 timed parts: Mathematics — 50 questions, 70 minutes; Analytical Ability & Logical Reasoning — 40 questions, 30 minutes; Computer Awareness & General English — 30 questions, 20 minutes.
• Each section runs on its own clock. When a section''s time ends it is locked and you are moved to the next section automatically.
• Marking: Mathematics +12 / −3 · Analytical Ability & Logical Reasoning +6 / −1.5 · Computer Awareness +6 / −1.5 · General English +4 / −1.
• There is no penalty for unanswered questions.
• Use the palette to navigate within the current section, and mark questions for review to revisit them before the section ends.
• The paper is auto-submitted when the final section ends; you may also submit early from the header.
• Answers are scored on the server. Correct answers and explanations appear on your scorecard only after you submit.'
where t.title = 'NIMCET Mock Test 01 — Full Length';

-- 5. Verification — the editor shows these result sets.
select s.section,
       count(*)      as questions,
       min(s.plus)   as marks_per_correct,
       min(s.minus)  as marks_per_wrong,
       sum(s.plus)   as max_marks
from seed_mock01 s
group by s.section
order by min(s.seq);

select count(*) as total_questions, sum(s.plus) as total_max_marks from seed_mock01 s;

select t.title, t.published, t.minutes, array_length(t.question_ids, 1) as linked_questions, t.sections
from public.tests t
where t.title = 'NIMCET Mock Test 01 — Full Length';

commit;
